Welcome to Rakudo™ v2026.08.my @pairs = 1, 3 Z 2, 4;
say @pairs.raku;
my $first = (1, 3) X (2, 4);
say $first.raku;

Welcome to Rakudo™ v2026.08.my @r = <b c a> ==> sort();
say @r;
<b c a> ==> sort() ==> my @s;
say @s;

Welcome to Rakudo™ v2026.08.say !1 ~~ 2;
say not 1 ~~ 2;
say (not 1, 42)[1];
say (so 0, 1).raku;

Welcome to Rakudo™ v2026.08.say (0 andthen "0 is defined");
say (5 andthen $_ * 2 andthen $_ + 1);
say (Any andthen 2).raku;
say (Any orelse "fallback");

Welcome to Rakudo™ v2026.08.say 1 !== 2;
say 1 !eqv 2;
say 1 !~~ Str;
say 1 !> 2 !< 3;

Welcome to Rakudo™ v2026.08.say 1 < 2 < 3;
say 1 < 3 > 2;
say 5 > 3 > 1 > 0;
my $calls = 0;
sub middle { $calls++; 2 }
say 1 < middle() < 3, " after $calls call";

Welcome to Rakudo™ v2026.08.say 1 R- 3;
say 2 Rx "ab";
say 1 R- 2 * 3;
say [R~] <a b c>;

Welcome to Rakudo™ v2026.08.say 1 ~ 2 * 3;
say 2 x 2 + 3;
say 2 x 2 ~ 3;
say 1 + 2 ~ 3;
